\documentclass{article}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage[paperwidth=12cm, paperheight=8cm, margin=0.5cm]{geometry}
\usepackage{xeCJK}
\setCJKmainfont{SimSun}

\begin{document}
\centering
\begin{tikzpicture}
\begin{axis}[
    width=0.9\textwidth,
    height=0.7\textwidth,
    title={2021-2026年数据变化趋势},
    xlabel={年份},
    ylabel={数值（万）},
    xmin=2020.5, xmax=2026.5,
    ymin=300, ymax=500,
    xtick={2021,2022,2023,2024,2025,2026},
    xticklabels={2021年,2022年,2023年,2024年,2025年,2026年},
    ymajorgrids=true,
    grid style=dashed,
    legend pos=north east,
    legend style={cells={anchor=west}},
    tick label style={font=\small},
    label style={font=\small},
    title style={font=\large\bfseries}
]

% 绘制折线
\addplot[
    color=blue,
    mark=*,
    mark size=2pt,
    line width=1.2pt,
    mark options={fill=white}
]
coordinates {
    (2021, 377)
    (2022, 457)
    (2023, 474)
    (2024, 438)
    (2025, 388)
    (2026, 343)
};

% 在数据点上添加数值标签
\addplot[
    nodes near coords,
    only marks,
    point meta=explicit symbolic,
    mark=none,
    font=\footnotesize
]
coordinates {
    (2021, 377) [377万]
    (2022, 457) [457万]
    (2023, 474) [474万]
    (2024, 438) [438万]
    (2025, 388) [388万]
    (2026, 343) [343万]
};

\legend{数据趋势}

\end{axis}
\end{tikzpicture}
\end{document}
